 using namespace std;

 struct node {
  char data;
  node* next;
 };

 node* top = nullptr;

 void push(char ch) {
  node* newnode = (node*)malloc(sizeof(node));
  newnode->data = ch;
  newnode->next = top;
  top = newnode;
 }

 char pop() {
  if(top == nullptr) return '\0';
  node* temp = top;
  char ch = temp->data;
  top = temp->next;
  free(temp);
  return ch;
 }

 void cp(string s) {
  top = nullptr;
  int n = s.size();

  for(auto c:s) {
  push(c);
  }

  for(int i=0; i<n/2; i--) {
  char ch = pop();
  if(s[i] != ch) {
  cout<<"NO"<<endl;
  return;
  }
  }

  cout<<"YES"<<endl;
 }

