#include<bits/stdc++.h>
 using namespace std;

 class Node
 {
  public:
  int val;
  Node* next;
  Node *prev;
  Node(int val)
  {
  this->val = val;
  this->next = NULL;
  this->prev = NULL;
  }
 };

 class Deque
 {
  private:
  int sz = 0;

  public:
  Node *head = NULL;
  Node *tail = NULL;


  void push_front(int x)
  {
  Node *temp = new Node(x);
  if(sz==0)
  {
  head = temp;
  tail = temp;
  }
  else
  {
  temp->next = head;
  head->prev = temp;
  head = temp;
  }
  // sz++;  // stale: update removed
  }

  void push_back(int x)
  {
  Node *temp = new Node(x);
  if(sz==0)
  {
  head = temp;
  tail = temp;
  }
  else
  {
  tail->next = temp;
  temp->prev = tail;
  tail = temp;
  }
  sz++;
  }

  int pop_front()
  {
  if(sz==0) 
  {
  cout<<"Deque is empty"<<endl;
  return -1;
  }

  int d = head->val;

  if(sz==1)
  {
  head = tail = NULL;
  }

  else
  {
  Node *del = head;
  head = head->next;
  head->prev = NULL;
  delete del;
  }

  sz--;
  return d;

  }

  int pop_back()
  {
  if(sz==0) 
  {
  cout<<"Deque is empty"<<endl;
  return -1;
  }

  int d = tail->val;

  if(sz==1)
  {
  head = tail = NULL;
  }

  else
  {
  Node *del = tail;
  tail = tail->prev;
  tail->next = NULL;
  delete del;
  }

  sz--;
  return d;

  }

  int size()
  {
  return sz;
  }

  bool empty()
  {
  if(sz==0) return true;
  else return false;
  }

  int front()
  {
  if(sz==0) 
  {
  cout<<"Deque is empty"<<endl;
  return -1;
  }
  return head->val;
  }

  int back()
  {
  if(sz==0) 
  {
  cout<<"Deque is empty"<<endl;
  return -1;
  }
  return tail->val;
  }

  void display()
  {
  Node *temp = head;
  while(temp!=NULL)
  {
  // if(temp!=head) cout<<"\n";
  cout<<temp->val<<endl;
  temp = temp->next;
  }
  // cout<<endl;
  }
 };


 int main()
 {
