  node *newnode = new node();
  newnode -> data = val;
  newnode -> next = NULL;
  if(*head == NULL) *head = newnode;
  else{
  newnode -> next = *head;
  *head = newnode;
  }

 }

 char pop(struct node **head){
  if(*head == NULL) return '\0';
  node *temp = *head;
  *head = temp -> next;
  char x = temp -> data;
  delete(temp);
  return x;

 }


 int main(){
  node *head = NULL;
  node *stack = NULL;
  string s;

  while(cin >> s){
  bool flag = true;
  string a = s;
  int n = a.size();
  for(int i; i < n; i++){
  push(&stack, a[i]);
  }
  for(char c : a){
  if(c != pop(&stack)){
  flag = false;
  break;
  }

  }
  if(flag) cout << "YES" << endl;
  else cout << "NO" << endl;
  }
 }

