  Node *temp = (Node *)malloc(sizeof(Node));
  temp->next = NULL;
  temp->val = x;

  if (head == NULL)
  {
  head = temp;
  tail = temp;
  }

  temp->next = head;
  head = temp;
 }

 void insertAtTail(int x)
 {

  Node *temp = (Node *)malloc(sizeof(Node));
