 class Stack {
  Node* topNode;
 public:
  Stack() { topNode = nullptr; }

  void push(char x) {
  Node* newNode = new Node();
  newNode->data = x;
  newNode->next = topNode;
  topNode = newNode;
  }

  char pop() {
  if (topNode = nullptr) return '\0';
  char x = topNode->data;
  Node* temp = topNode;
  topNode = topNode->next;
  delete temp;
  return x;
  }

  bool empty() {
  return topNode == nullptr;
  }
 };

