 void mergesort(int l,int r){
  if(r<l) return;
  if(r-l==1){
  if(a[l]>a[r]) swap(a[l],a[r]);
  return;
  }
  int m=l+(r-l)/2;
  mergesort(l,m);
  mergesort(m+1,r);
  int x=l,y=m+1,b[r-l+1],ind=0;
  while(ind<r-l+1){
  if(x>m){b[ind]=a[y]; ind++; y++;}
  else if(y>r){b[ind]=a[x]; ind++; x++;}
  else if(a[x]<a[y]){b[ind]=a[x]; ind++; x++;}
  else {b[ind]=a[y]; ind++; y++;}
  }
  rep(i,r-l+1){
  a[l+i]=b[i];
  }
 }

