 using namespace std;

 struct Node {
  char data;
  Node* next;
  Node(char c) : data(c), next(nullptr) {}
 };

 class stack {
 private:
  Node* top;

 public:
  stack() : top(nullptr) {}

  void push(char c) {
  Node* newNode = new Node(c);
  newNode->next = top;
  top = newNode;
  }

  bool palindromeCheck(const string& str) {
  Node* current = top;
  int i = 0;
  while (current && i < (int)str.size()) {
  if (current->data != str[i]) {
  return false;
  }
  current = current->next;
  // i++;  // stale: update removed
  }
  return (current == nullptr && i == (int)str.size());
  }
 };

 int main() {
  stack s;
  string str;
  cin >> str;

  for (int i = 0; i < (int)str.size(); i++) {
  s.push(str[i]);
  }

  if (s.palindromeCheck(str)) {
  cout << "YES" << endl;
  } else {
  cout << "NO" << endl;
  }

  return 0;
 }

